#!/usr/bin/env python3
"""
SEND_TEST_PACKET.py

Sends one correctly-formatted, AES-256-GCM encrypted SOS packet directly to
OFFGRID_SOS_RX_HARDCODED.py over UDP — bypassing bladeRF/GNU Radio entirely.

Use this to verify the RX script + React dashboard pipeline works end-to-end
before your actual RF hardware is wired up. Run OFFGRID_SOS_RX_HARDCODED.py
first, then run this script (as many times as you like — each run bumps the
sequence number so it won't get replay-blocked).

Requires: pip install cryptography --break-system-packages   (if not already installed)
"""

import os
import socket
import struct
import time

from cryptography.hazmat.primitives.ciphers.aead import AESGCM

# Must match OFFGRID_SOS_RX_HARDCODED.py exactly
AES_KEY = bytes.fromhex(
    "000102030405060708090A0B0C0D0E0F"
    "101112131415161718191A1B1C1D1E1F"
)
TARGET_HOST = "127.0.0.1"
TARGET_PORT = 40868

DEVICE_ID = 1001
TAG_ID = b"RFC"
STRUCT_FMT = "<4sIIiihHIBB"

# Bump this each run, or keep a small file to auto-increment it.
SEQ_FILE = os.path.join(os.path.dirname(__file__), ".test_seq")


def next_sequence() -> int:
    seq = 1
    if os.path.exists(SEQ_FILE):
        try:
            seq = int(open(SEQ_FILE).read().strip()) + 1
        except ValueError:
            pass
    with open(SEQ_FILE, "w") as f:
        f.write(str(seq))
    return seq


def build_packet(alert_type: int, lat: float, lon: float, altitude_m: int,
                  hdop: float, battery: int, sequence: int) -> bytes:
    plaintext = struct.pack(
        STRUCT_FMT,
        TAG_ID.ljust(4, b"\0"),
        DEVICE_ID,
        sequence,
        int(lat * 10_000_000),
        int(lon * 10_000_000),
        altitude_m,
        int(hdop * 100),
        int(time.time()),
        alert_type,
        battery,
    )
    iv = os.urandom(12)
    aad = struct.pack("<I", DEVICE_ID)
    ct_and_tag = AESGCM(AES_KEY).encrypt(iv, plaintext, aad)  # ciphertext(30) + tag(16)
    packet = b"SO" + struct.pack("<I", DEVICE_ID) + iv + ct_and_tag
    assert len(packet) == 64, f"packet is {len(packet)} bytes, expected 64"
    return packet


def main():
    sequence = next_sequence()
    # alert_type: 1 = CRITICAL_SOS, 0 = HEARTBEAT
    packet = build_packet(
        alert_type=1,
        lat=13.0827,
        lon=80.2707,
        altitude_m=15,
        hdop=1.05,
        battery=88,
        sequence=sequence,
    )

    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.sendto(packet, (TARGET_HOST, TARGET_PORT))
    sock.close()

    print(f"Sent test SOS packet (sequence {sequence}, {len(packet)} bytes) "
          f"to {TARGET_HOST}:{TARGET_PORT}")
    print("Check the RX script's console output and the dashboard for the decoded alert.")


if __name__ == "__main__":
    main()
